 const sync=()=>{const v=selectedVariant();$('#detail-price').innerHTML=v?`${fmt(v.price)}${v.compare>v.price?` <del>${fmt(v.compare)}</del>`:''}`:fmt(p.price);$('#variant-status').textContent=v?.available?'Disponible para pedir · Confirmamos stock al coordinar.':v?'Esta opción está agotada. Podés consultar por reposición.':'Esta combinación no está disponible. Elegí otra opción.';$('#detail-add').disabled=!v?.available;$('#detail-add').textContent=v?.available?'Agregar al carrito':'Sin disponibilidad';$$('[data-option-index]').forEach(b=>b.setAttribute('aria-pressed',String(selectedOptions[+b.dataset.optionIndex]===b.dataset.optionValue)));if(v){const params=new URLSearchParams(location.search);params.set('variante',v.id);updateUrl(params);if(v.image)$('#product-photo').src=v.image}$('#detail-minus').disabled=detailQuantity<=1;$('#detail-plus').disabled=detailQuantity>=99};
